  );

  const newCart = {
    items: updatedItems,
    totalAmount: calculateTotalAmount(updatedItems),
  };
  saveCart(newCart);
  return newCart;
};

export const updateItemQuantity = (menuItemId: UUID, quantity: number): Cart => {
  const currentCart = getCart();
  let updatedItems: CartItem[];

  if (quantity <= 0) {
