      (item) => item.menuItemId !== menuItemId
    );
  } else {
    updatedItems = currentCart.items.map((item) =>
      item.menuItemId === menuItemId ? { ...item, quantity } : item
    );
  }

  const newCart = {
    items: updatedItems,
    totalAmount: calculateTotalAmount(updatedItems),
  };
  saveCart(newCart);
